    "subject_id" uuid NOT NULL,
    "subject_table" text NOT NULL,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_slugs_period_years_are_ordered" CHECK (
        (
            ("from_year" IS NULL)
            OR ("to_year" IS NULL)
            OR ("from_year" <= "to_year")
        )
    ),
    PRIMARY KEY ("id")
);

