    "centroid" AS "centroid",
    "feature_id" AS "feature_id",
    "geometry" AS "geometry",
    "id" AS "id"
FROM
    "geography"."geometries"
WHERE
    "to_year" IS NULL;

CREATE FUNCTION "geography"."scheme_identifiers_identifier_scheme_id" () RETURNS trigger LANGUAGE plpgsql AS $scheme$
BEGIN
  IF NEW."identifier_scheme_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM "reference"."values" v
    JOIN "reference"."schemes" s ON s."id" = v."scheme_id"
    WHERE v."id" = NEW."identifier_scheme_id" AND s."code" = 'ref.sch.geo.identifier.scheme'
    FOR SHARE OF v, s
  ) THEN
    RAISE EXCEPTION 'referenced value belongs to a different scheme' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$scheme$;

